// ---------- Utilidades ----------
const LOGO = 'data:image/jpeg;base64,';
const TZ = 'America/Mexico_City';
const $ = (s, r = document) => r.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const hoy = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const ahora = () => new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit' }).format(new Date());
const MXN = new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' });
const money = (c) => MXN.format((c || 0) / 100);
const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const fecha = (f) => (f ? `${Number(f.slice(8, 10))} ${MESES[Number(f.slice(5, 7)) - 1]} ${f.slice(0, 4)}` : '—');
const centavos = (v) => Math.round(parseFloat(String(v || '0').replace(/,/g, '')) * 100) || 0;
const pesos = (c) => ((c || 0) / 100).toFixed(2);
const nid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const DIAS = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];
const CLASES = { mensualidad: 'Mensualidad', visita: 'Visita', paquete: 'Paquete de sesiones', inscripcion: 'Inscripción', renta: 'Renta', personalizado: 'Entrenamiento personalizado', producto: 'Producto' };
const ESTADOS = {
  activa: ['ok', 'Activa'], por_vencer: ['warn', 'Por vencer'], vencida: ['bad', 'Vencida'], agotada: ['bad', 'Sin sesiones'],
  suspendida: ['off', 'Suspendida'], cancelada: ['off', 'Cancelada'], programada: ['info', 'Programada'],
  pagado: ['ok', 'Pagado'], parcial: ['warn', 'Pago parcial'], pendiente: ['bad', 'Pendiente'], cancelado: ['off', 'Cancelado'],
  abierto: ['info', 'Abierto'], ordenado: ['warn', 'Pedido al proveedor'], recibido: ['ok', 'Recibido'], cerrado: ['off', 'Entregado y cerrado'],
};
const chip = (e) => { const [c, t] = ESTADOS[e] || ['off', e]; return `<span class="chip ${c}">${esc(t)}</span>`; };

// ---------- Estado ----------
const COLS = ['areas', 'tiposCliente', 'conceptos', 'precios', 'equipos', 'entrenadores', 'formasPago', 'recursos', 'clientes', 'membresias', 'cargos', 'pagos', 'clases', 'reservaciones', 'pedidos', 'config'];
const S = { asistencias: [], dias: {} };
COLS.forEach((c) => { S[c] = []; });
let db = null, user = null, descargas = null;
let me = { id: null, name: '' };
let perfiles = {};
const ui = { ruta: 'tablero', cargado: false, lento: false, error: null, soloLectura: false, clienteId: null, q: '', fTipo: '', fActivo: '1',
  fEstado: '', fArea: '', cobrosTab: 'cargos', qCobros: '', corteFecha: hoy(), asisFecha: hoy(), resFecha: hoy(),
  repDesde: hoy().slice(0, 8) + '01', repHasta: hoy(), cat: 'conceptos', tEquipo: '', tPend: '', pedidoId: null };
const RUTAS = [['tablero', 'Tablero'], ['clientes', 'Clientes'], ['membresias', 'Membresías'], ['cobros', 'Cobros'], ['adeudos', 'Adeudos y corte'],
  ['asistencia', 'Asistencia'], ['horarios', 'Horarios'], ['tallas', 'Tallas'], ['pedidos', 'Pedidos'], ['reportes', 'Reportes'], ['catalogos', 'Catálogos']];
// Uniformes de equipos: prendas y tallas sugeridas (se puede escribir otra, p. ej. 7 1/4).
const PRENDAS = [['cachucha', 'Cachucha'], ['jersey', 'Jersey'], ['pantalonera', 'Pantalonera']];
const TALLAS = ['XCH', 'CH', 'M', 'G', 'XG', 'XXG'];
const TALLAS_SUG = { cachucha: ['CH', 'M', 'G', 'XG', 'CH/M', 'M/G', 'G/XG', 'Unitalla'], jersey: TALLAS, pantalonera: TALLAS };
const tallasDe = (c) => c.tallas || {};
// Un jugador puede estar en varios equipos (equipoIds); equipoId es el dato anterior, de un solo equipo.
const equiposDe = (c) => (Array.isArray(c.equipoIds) ? c.equipoIds : c.equipoId ? [c.equipoId] : []);
const equiposTxt = (c) => equiposDe(c).map((e) => nom('equipos', e)).join(', ');
// Número y leyenda van por equipo. Lo capturado antes (en tallas) cuenta para su primer equipo.
const SIN_EQUIPO = 'sinEquipo';
function uniDe(c, eq) {
  const u = (c.uniformes || {})[eq || SIN_EQUIPO];
  if (u) return u;
  const t = tallasDe(c);
  return (eq || '') === (equiposDe(c)[0] || '') ? { numero: t.numero || '', leyenda: t.leyenda || '' } : {};
}
// Una fila por jugador y equipo: quien juega en dos equipos lleva dos uniformes.
const ordenTalla = (a, b) => { const i = TALLAS.indexOf(a), j = TALLAS.indexOf(b); return (i < 0 ? 99 : i) - (j < 0 ? 99 : j) || a.localeCompare(b, 'es', { numeric: true }); };
function jugadoresTallas() {
  const pat = new Set(S.tiposCliente.filter((t) => t.patrocinado).map((t) => t.id));
  return S.clientes.filter((c) => c.activo !== false && (equiposDe(c).length || pat.has(c.tipoClienteId)) && (!ui.tPend || PRENDAS.some(([k]) => !tallasDe(c)[k])))
    .flatMap((c) => (equiposDe(c).length ? equiposDe(c) : ['']).map((eq) => ({ c, eq })))
    .filter((x) => !ui.tEquipo || x.eq === ui.tEquipo)
    .sort((a, b) => nom('equipos', a.eq, '').localeCompare(nom('equipos', b.eq, ''), 'es') || a.c.nombre.localeCompare(b.c.nombre, 'es'));
}

// Pedidos especiales de artículos para venta. Los renglones van en un mapa para que dos equipos capturen a la vez.
const ARTICULOS = ['Sudadera', 'Chamarra', 'Cachucha', 'Jersey', 'Pantalonera', 'Playera'];
const ESTADOS_PEDIDO = ['abierto', 'ordenado', 'recibido', 'cerrado', 'cancelado'];
const lineasDe = (p) => Object.entries(p.lineas || {}).filter(([, l]) => l).map(([id, l]) => ({ id, ...l }));
const piezasDe = (p) => lineasDe(p).reduce((t, l) => t + (l.cantidad || 0), 0);
const importeDe = (p) => lineasDe(p).reduce((t, l) => t + (l.cantidad || 0) * (l.precio || 0), 0);
const paraQuien = (l) => (l.clienteId ? nom('clientes', l.clienteId) : l.nombre || 'Existencia del gimnasio');
// Cargo vigente con el que se cobró un renglón de pedido (si se canceló, el renglón vuelve a estar sin cobrar).
const cargoDeLinea = (l) => { const c = l.cargoId && by('cargos', l.cargoId); return c && !c.cancelado ? c : null; };
// Los cargos de pedidos no llevan concepto del catálogo: se describen con el artículo.
const conceptoDe = (g) => g.descripcion || nom('conceptos', g.conceptoId);
const PED = '_pedidos';
// Una reservación es de un cliente o de un equipo o grupo externo (grupo: su nombre; no son los equipos del catálogo).
const grupoDe = (r) => r.grupo || (r.equipoId ? nom('equipos', r.equipoId) : '');
const quienReserva = (r) => grupoDe(r) || nom('clientes', r.clienteId);
function choqueReserva(v) {
  const c = R.traslapes(S.reservaciones, v)[0];
  if (!c) return '';
  const por = c.recursoId === v.recursoId ? nom('recursos', c.recursoId) : 'mismo entrenador';
  return `Se traslapa con la reservación de ${quienReserva(c)} (${c.inicio}–${c.fin}, ${por}).`;
}
const pedidoFijo = (p) => p.estado === 'cancelado' || p.estado === 'cerrado';

const by = (col, id) => S[col].find((x) => x.id === id);
const nom = (col, id, alt = '—') => (by(col, id) || {}).nombre || alt;
const activos = (col) => S[col].filter((x) => x.activo !== false).sort((a, b) => String(a.nombre).localeCompare(b.nombre, 'es'));
const diasAviso = () => Number((by('config', 'general') || {}).diasAviso) || 7;
const estadoM = (m) => R.estadoMembresia(m, hoy(), diasAviso());
const sello = () => ({ creado: new Date().toISOString(), creadoPor: me.id || '' });
const quien = (id) => (perfiles[id] && perfiles[id].name) || (id && id === me.id ? 'Tú' : id ? 'Personal' : '—');
const opts = (col, sel, vacio) => (vacio != null ? `<option value="">${esc(vacio)}</option>` : '')
  + activos(col).map((x) => `<option value="${esc(x.id)}"${x.id === sel ? ' selected' : ''}>${esc(x.nombre)}</option>`).join('');
const areasTxt = (ids) => (ids && ids.length ? ids.map((a) => nom('areas', a)).join(', ') : 'General');

// ---------- Datos ----------
async function guardar(col, id, data) { const { id: _x, ...body } = data; await db.collection(col).doc(id).set(body); }
async function parchar(col, id, patch) { await db.collection(col).doc(id).update(patch); }
const tabId = nid();
async function folio(tipo) {
  if (db.folio) return db.folio(tipo); // servidor propio: consecutivo atómico
  const ref = db.doc('config/folios');
  for (let i = 0; i < 8; i++) {
    try { const r = await ref.acquire({ holder: tabId, ttlMs: 4000 }); if (r.acquired) break; } catch (e) { break; }
    await sleep(400);
  }
  const snap = await ref.get();
  const n = ((snap.exists && snap.data()[tipo]) || 0) + 1;
  if (snap.exists) await ref.update({ [tipo]: n }); else await ref.set({ [tipo]: n });
  return n;
}
function pedirPerfiles(ids) {
  if (!user) return;
  const faltan = [...new Set(ids)].filter((i) => i && !(i in perfiles));
  if (!faltan.length) return;
  faltan.forEach((i) => { perfiles[i] = null; });
  user.profiles(faltan).then((ps) => { Object.assign(perfiles, ps); pintar(); });
}

async function iniciar() {
  $('#logo').src = LOGO;
  render();
  const c = window.claude;
  if (!c || !c.use) { ui.error = 'sin_db'; render(); return; }
  [db, user, descargas] = await Promise.all([c.use('db'), c.use('user'), c.use('downloads')]);
  if (!db) { ui.error = 'sin_db'; render(); return; }
  if (user) {
    me = await user.me();
    ui.soloLectura = (await user.can('data.write')) === false;
    $('#quien').textContent = me.name ? `Sesión: ${me.name}` : '';
  }
  const pend = new Set([...COLS, 'dias']);
  const timer = setTimeout(() => { if (!ui.cargado) { ui.lento = true; pintar(); } }, 10000);
  const listo = (k, snap) => {
    if (snap.metadata && snap.metadata.fromCache && pend.has(k) && snap.empty) return;
    pend.delete(k);
    if (!pend.size && !ui.cargado) { ui.cargado = true; ui.lento = false; clearTimeout(timer); }
  };
  const falla = (e) => { ui.error = e.code || 'unavailable'; clearTimeout(timer); pintar(); };
  COLS.forEach((col) => db.collection(col).onSnapshot((snap) => {
    S[col] = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
    listo(col, snap); pintar();
  }, falla));
  db.collection('asistenciasDia').orderBy('fecha', 'desc').limit(180).onSnapshot((snap) => {
    S.dias = {}; S.asistencias = [];
    snap.docs.forEach((d) => {
      const x = d.data(); S.dias[d.id] = true;
      Object.entries(x.entradas || {}).forEach(([id, e]) => S.asistencias.push({ id, fecha: d.id, ...e }));
    });
    listo('dias', snap); pintar();
  }, falla);
}

// ---------- Render ----------
let pendiente = false;
function pintar() { if (pendiente) return; pendiente = true; requestAnimationFrame(() => { pendiente = false; render(); }); }
function render() {
  const ruta = (location.hash || '#tablero').slice(1);
  ui.ruta = RUTAS.some((r) => r[0] === ruta) ? ruta : 'tablero';
  $('#nav').innerHTML = RUTAS.map(([k, t]) => `<a href="#${k}"${k === ui.ruta ? ' aria-current="page"' : ''}>${t}</a>`).join('');
  const act = document.activeElement; const fid = act && act.id && $('#view').contains(act) ? act.id : null;
  const pos = fid && act.selectionStart != null ? act.selectionStart : null;
  const vals = {}; $('#view').querySelectorAll('input[id],select[id],textarea[id]').forEach((e) => { if (!e.dataset.ui) vals[e.id] = e.value; });
  let html;
  if (ui.error === 'sin_db') html = `<div class="note bad">No se pudo conectar con la base de datos del portal. Abre el portal desde Claude con tu sesión iniciada. Mientras tanto no se puede capturar información.</div>`;
  else if (ui.error) html = `<div class="note bad">Se perdió el acceso a los datos (${esc(ui.error)}). Vuelve a abrir el portal.</div>`;
  else if (!ui.cargado) html = `<div class="note info">${ui.lento ? 'Los datos aún no responden. Revisa tu conexión; el portal seguirá intentando.' : 'Cargando datos del gimnasio…'}</div>`;
  else html = (ui.soloLectura ? `<div class="note">Tu acceso es de solo lectura: puedes consultar, pero no capturar.</div>` : '') + VISTAS[ui.ruta]();
  $('#view').innerHTML = `<div class="wrap">${html}</div>`;
  Object.entries(vals).forEach(([i, v]) => { const e = document.getElementById(i); if (e && $('#view').contains(e)) e.value = v; });
  if (fid) { const el = document.getElementById(fid); if (el) { el.focus(); if (pos != null) try { el.setSelectionRange(pos, pos); } catch (e) {} } }
}
const cabeza = (t, sub, extra = '') => `<div class="head"><div><h1>${t}</h1>${sub ? `<div class="sub">${sub}</div>` : ''}</div><div class="row">${extra}</div></div>`;
const tabla = (heads, filas, vacio) => (filas.length
  ? `<div class="scroll"><table><thead><tr>${heads.map((h) => `<th${h.startsWith('#') ? ' class="n"' : ''}>${esc(h.replace(/^#/, ''))}</th>`).join('')}</tr></thead><tbody>${filas.join('')}</tbody></table></div>`
  : `<div class="empty">${vacio}</div>`);
function barras(obj, etiqueta) {
  const e = Object.entries(obj).sort((a, b) => b[1] - a[1]);
  if (!e.length) return `<div class="empty">Sin movimientos en el periodo.</div>`;
  const max = Math.max(...e.map((x) => x[1])) || 1;
  return `<div class="bars">${e.map(([k, v]) => `<div class="bar"><span>${esc(etiqueta(k))}</span><div class="track"><i style="width:${Math.max(1, (v / max) * 100)}%"></i></div><b>${money(v)}</b></div>`).join('')}</div>`;
}
const areaNom = (k) => (k === 'general' ? 'General (sin área)' : nom('areas', k, k));
const saldoCliente = (id) => S.cargos.filter((c) => c.clienteId === id).reduce((s, c) => s + R.saldoCargo(c, S.pagos), 0);
function resumenMembresia(clienteId) {
  const ms = S.membresias.filter((m) => m.clienteId === clienteId).map(estadoM);
  for (const e of ['activa', 'por_vencer', 'programada', 'suspendida', 'agotada', 'vencida']) if (ms.includes(e)) return chip(e);
  return '<span class="muted">Sin membresía</span>';
}

const VISTAS = {
  tablero() {
    const h = hoy(), ini = h.slice(0, 8) + '01';
    const conAcceso = new Set(S.membresias.filter((m) => R.daAcceso(estadoM(m))).map((m) => m.clienteId));
    const ing = R.ingresos(S.pagos, S.cargos, S.clientes, ini, h);
    const ade = R.adeudos(S.cargos, S.pagos, h);
    const porVencer = S.membresias.filter((m) => estadoM(m) === 'por_vencer').sort((a, b) => (a.fin < b.fin ? -1 : 1));
    const vacio = !S.conceptos.length && !S.clientes.length
      ? `<div class="note info">Aún no hay catálogos. Entra a <a href="#catalogos">Catálogos</a> para dar de alta áreas, tipos de cliente, conceptos y precios.</div>` : '';
    return cabeza('Tablero', `Hoy, ${fecha(h)}`, `<button class="pri" data-a="vender">Nueva venta</button><a class="btn" href="#asistencia">Registrar entrada</a>`) + vacio
      + `<div class="kpis">
        <div class="kpi"><span>Socios activos</span><b>${conAcceso.size}</b></div>
        <div class="kpi"><span>Ingresos del mes</span><b>${money(ing.total)}</b></div>
        <div class="kpi"><span>Patrocinado del mes</span><b>${money(R.patrocinioPeriodo(S.cargos, ini, h))}</b></div>
        <div class="kpi"><span>Adeudos</span><b>${money(ade.reduce((s, a) => s + a.saldo, 0))}</b><small>${ade.length} cliente(s)</small></div>
        <div class="kpi"><span>Entradas hoy</span><b>${S.asistencias.filter((a) => a.fecha === h).length}</b></div>
        <div class="kpi"><span>Por vencer</span><b>${porVencer.length}</b><small>en ${diasAviso()} días</small></div>
      </div>
      <div class="cols">
        <div class="panel"><h3>Ingresos del mes por área</h3>${barras(ing.porArea, areaNom)}</div>
        <div class="panel"><h3>Ingresos del mes por tipo de cliente</h3>${barras(ing.porTipo, (k) => nom('tiposCliente', k, k))}</div>
      </div>
      <div class="cols">
        <div class="panel"><h3>Membresías por vencer</h3>${tabla(['Cliente', 'Concepto', 'Vence', ''], porVencer.slice(0, 12).map((m) => `<tr><td>${esc(nom('clientes', m.clienteId))}</td><td>${esc(nom('conceptos', m.conceptoId))}</td><td>${fecha(m.fin)}</td><td class="n"><button class="mini" data-a="vender" data-cliente="${m.clienteId}" data-concepto="${m.conceptoId}">Renovar</button></td></tr>`), 'Ninguna membresía vence en los próximos días.')}</div>
        <div class="panel"><h3>Adeudos más altos</h3>${tabla(['Cliente', '#Saldo', '#Días'], ade.slice(0, 8).map((a) => `<tr class="click" data-a="verCliente" data-id="${a.clienteId}"><td>${esc(nom('clientes', a.clienteId))}</td><td class="n">${money(a.saldo)}</td><td class="n">${a.antiguedad}</td></tr>`), 'Nadie debe. Cartera al corriente.')}</div>
      </div>`;
  },

  clientes() {
    if (ui.clienteId && by('clientes', ui.clienteId)) return expediente(by('clientes', ui.clienteId));
    const q = ui.q.trim().toLowerCase();
    const lista = S.clientes.filter((c) => (!q || `${c.nombre} ${c.telefono || ''}`.toLowerCase().includes(q))
      && (!ui.fTipo || c.tipoClienteId === ui.fTipo) && (ui.fActivo === '' || (c.activo !== false) === (ui.fActivo === '1')))
      .sort((a, b) => a.nombre.localeCompare(b.nombre, 'es'));
    return cabeza('Clientes', `${lista.length} de ${S.clientes.length}`, `<button class="pri" data-a="clienteForm">Nuevo cliente</button>`)
      + `<div class="row"><input id="q" class="grow" placeholder="Buscar por nombre o teléfono" value="${esc(ui.q)}" data-ui="q">
        <select id="fTipo" data-ui="fTipo" style="width:auto">${opts('tiposCliente', ui.fTipo, 'Todos los tipos')}</select>
        <select id="fActivo" data-ui="fActivo" style="width:auto"><option value="1"${ui.fActivo === '1' ? ' selected' : ''}>Activos</option><option value="0"${ui.fActivo === '0' ? ' selected' : ''}>Inactivos</option><option value=""${ui.fActivo === '' ? ' selected' : ''}>Todos</option></select></div>
      <div class="panel">${tabla(['Nombre', 'Tipo', 'Equipo', 'Teléfono', 'Membresía', '#Saldo'], lista.slice(0, 300).map((c) => {
        const s = saldoCliente(c.id);
        return `<tr class="click" data-a="verCliente" data-id="${c.id}"><td>${esc(c.nombre)}</td><td>${esc(nom('tiposCliente', c.tipoClienteId))}</td><td>${esc(equiposTxt(c) || '—')}</td><td>${esc(c.telefono || '—')}</td><td>${resumenMembresia(c.id)}</td><td class="n">${s ? money(s) : '—'}</td></tr>`;
      }), S.clientes.length ? 'Ningún cliente coincide con el filtro.' : 'Todavía no hay clientes. Usa “Nuevo cliente” para dar de alta al primero.')}</div>`;
  },

  membresias() {
    const lista = S.membresias.map((m) => ({ m, e: estadoM(m), c: by('conceptos', m.conceptoId) || {} }))
      .filter((x) => (!ui.fEstado || x.e === ui.fEstado) && (!ui.fArea || (x.c.areaIds || []).includes(ui.fArea)))
      .sort((a, b) => (a.m.fin < b.m.fin ? 1 : -1));
    return cabeza('Membresías y paquetes', `${lista.length} registro(s)`, `<button class="pri" data-a="vender">Nueva venta</button>`)
      + `<div class="row"><select id="fEstado" data-ui="fEstado" style="width:auto"><option value="">Todos los estados</option>${['activa', 'por_vencer', 'vencida', 'agotada', 'programada', 'suspendida', 'cancelada'].map((e) => `<option value="${e}"${ui.fEstado === e ? ' selected' : ''}>${ESTADOS[e][1]}</option>`).join('')}</select>
        <select id="fArea" data-ui="fArea" style="width:auto">${opts('areas', ui.fArea, 'Todas las áreas')}</select></div>
      <div class="panel">${tabla(['Cliente', 'Concepto', 'Inicio', 'Fin', 'Sesiones', 'Estado', ''], lista.slice(0, 300).map(({ m, e }) => filaMembresia(m, e, true)), 'No hay membresías con ese filtro.')}</div>`;
  },

  cobros() {
    const q = ui.qCobros.trim().toLowerCase();
    const coincide = (x) => !q || `${nom('clientes', x.clienteId)} ${x.folio}`.toLowerCase().includes(q);
    let cuerpo;
    if (ui.cobrosTab === 'cargos') {
      const l = S.cargos.filter(coincide).sort((a, b) => (b.folio || 0) - (a.folio || 0)).slice(0, 300);
      cuerpo = tabla(['Folio', 'Fecha', 'Cliente', 'Concepto', '#Total', '#Saldo', 'Estado', ''], l.map((c) => filaCargo(c, true)), 'Aún no hay cargos. Usa “Nueva venta”.');
    } else {
      const l = S.pagos.filter(coincide).sort((a, b) => (b.folio || 0) - (a.folio || 0)).slice(0, 300);
      pedirPerfiles(l.map((p) => p.creadoPor));
      cuerpo = tabla(['Folio', 'Fecha', 'Cliente', 'Forma', '#Monto', 'Registró', 'Estado', ''], l.map((p) => `<tr><td>P-${p.folio}</td><td>${fecha(p.fecha)}</td><td>${esc(nom('clientes', p.clienteId))}</td><td>${esc(nom('formasPago', p.formaPagoId))}</td><td class="n">${money(p.monto)}</td><td>${esc(quien(p.creadoPor))}</td><td>${p.cancelado ? chip('cancelado') : chip('pagado').replace('Pagado', 'Vigente')}</td><td class="n"><button class="mini" data-a="recibo" data-id="${p.id}">Recibo</button> ${p.cancelado ? '' : `<button class="mini danger" data-a="motivo" data-tipo="pago" data-id="${p.id}">Cancelar</button>`}</td></tr>`), 'Aún no hay pagos registrados.');
    }
    return cabeza('Cobros', 'Ventas, cargos y pagos', `<button class="pri" data-a="vender">Nueva venta</button>`)
      + `<div class="tabs" role="tablist">${[['cargos', 'Cargos'], ['pagos', 'Pagos']].map(([k, t]) => `<button role="tab" aria-selected="${ui.cobrosTab === k}" data-a="set" data-k="cobrosTab" data-v="${k}">${t}</button>`).join('')}</div>
      <input id="qCobros" placeholder="Buscar por cliente o folio" value="${esc(ui.qCobros)}" data-ui="qCobros">
      <div class="panel">${cuerpo}</div>`;
  },

  adeudos() {
    const ade = R.adeudos(S.cargos, S.pagos, hoy());
    const corte = R.corteCaja(S.pagos, ui.corteFecha);
    pedirPerfiles(Object.keys(corte.porUsuario));
    const lin = (o, f) => Object.entries(o).map(([k, v]) => `<tr><td>${esc(f(k))}</td><td class="n">${money(v)}</td></tr>`);
    return cabeza('Adeudos y corte de caja', `Cartera total: ${money(ade.reduce((s, a) => s + a.saldo, 0))}`)
      + `<div class="panel"><h3>Cartera por cliente</h3>${tabla(['Cliente', 'Teléfono', '#Cargos', '#Antigüedad (días)', '#Saldo', ''], ade.map((a) => `<tr><td>${esc(nom('clientes', a.clienteId))}</td><td>${esc((by('clientes', a.clienteId) || {}).telefono || '—')}</td><td class="n">${a.cargos.length}</td><td class="n">${a.antiguedad}</td><td class="n">${money(a.saldo)}</td><td class="n"><button class="mini" data-a="verCliente" data-id="${a.clienteId}">Ver y cobrar</button></td></tr>`), 'Nadie debe. Cartera al corriente.')}</div>
      <div class="panel"><div class="head"><h3>Corte de caja</h3><div class="row"><input type="date" id="corteFecha" data-ui="corteFecha" value="${ui.corteFecha}" style="width:auto"><button data-a="csvCorte">Descargar CSV</button></div></div>
        <div class="total">${money(corte.total)} <span class="muted small" style="font-family:var(--body)">cobrado el ${fecha(ui.corteFecha)} en ${corte.vigentes.length} pago(s)</span></div>
        <div class="cols"><div><h3>Por forma de pago</h3>${tabla(['Forma', '#Importe'], lin(corte.porForma, (k) => nom('formasPago', k)), 'Sin pagos ese día.')}</div>
        <div><h3>Por quien registró</h3>${tabla(['Persona', '#Importe'], lin(corte.porUsuario, quien), 'Sin pagos ese día.')}</div></div>
        ${corte.cancelados.length ? `<h3>Pagos cancelados</h3>${tabla(['Folio', 'Cliente', '#Monto', 'Motivo'], corte.cancelados.map((p) => `<tr><td>P-${p.folio}</td><td>${esc(nom('clientes', p.clienteId))}</td><td class="n">${money(p.monto)}</td><td>${esc(p.motivoCancelacion || '')}</td></tr>`), '')}` : ''}
      </div>`;
  },

  asistencia() {
    const l = S.asistencias.filter((a) => a.fecha === ui.asisFecha).sort((a, b) => (a.hora < b.hora ? 1 : -1));
    pedirPerfiles(l.map((a) => a.por));
    return cabeza('Asistencia', 'Registro de entradas')
      + `<form class="panel" data-form="checkin"><h3>Registrar entrada</h3><div class="form">
          <label class="f">Cliente<select name="clienteId" id="ci-cliente" required><option value="">Selecciona…</option>${S.clientes.filter((c) => c.activo !== false).sort((a, b) => a.nombre.localeCompare(b.nombre, 'es')).map((c) => `<option value="${c.id}">${esc(c.nombre)}</option>`).join('')}</select></label>
          <label class="f">Área<select name="areaId" id="ci-area" required>${opts('areas')}</select></label>
          <div style="align-self:end"><button class="pri">Registrar entrada</button></div></div><div class="err" id="ci-err"></div></form>
        <div class="panel"><div class="head"><h3>Bitácora</h3><div class="row"><input type="date" id="asisFecha" data-ui="asisFecha" value="${ui.asisFecha}" style="width:auto"><span class="muted">${l.length} entrada(s)</span></div></div>
        ${tabla(['Hora', 'Cliente', 'Área', 'Cubierta por', 'Registró'], l.map((a) => `<tr><td>${esc(a.hora)}</td><td>${esc(nom('clientes', a.clienteId))}</td><td>${esc(nom('areas', a.areaId))}</td><td>${a.excepcion ? `<span class="chip warn">Excepción</span> <span class="muted small">${esc(a.motivo || '')}</span>` : esc(nom('conceptos', (by('membresias', a.membresiaId) || {}).conceptoId))}</td><td>${esc(quien(a.por))}</td></tr>`), 'Sin entradas registradas ese día.')}</div>`;
  },

  horarios() {
    const res = S.reservaciones.filter((r) => r.fecha === ui.resFecha).sort((a, b) => (a.inicio < b.inicio ? -1 : 1));
    return cabeza('Horarios', 'Clases semanales y reservaciones', `<button data-a="claseForm">Nueva clase</button><button data-a="reservaEquipoForm">Reservar para equipo o grupo</button><button class="pri" data-a="reservaForm">Nueva reservación</button>`)
      + `<div class="panel"><h3>Clases de la semana</h3><div class="week">${DIAS.map((d, i) => `<div class="day"><b>${d}</b>${S.clases.filter((c) => c.activo !== false && Number(c.dia) === i).sort((a, b) => (a.inicio < b.inicio ? -1 : 1)).map((c) => `<button class="cls" data-a="claseForm" data-id="${c.id}">${esc(c.inicio)}–${esc(c.fin)} ${esc(c.nombre)}<small>${esc(nom('areas', c.areaId))} · ${esc(nom('entrenadores', c.entrenadorId, 'Sin entrenador'))} · cupo ${esc(c.cupo || '—')}</small></button>`).join('') || '<span class="muted small">Sin clases</span>'}</div>`).join('')}</div></div>
      <div class="panel"><div class="head"><h3>Reservaciones</h3><input type="date" id="resFecha" data-ui="resFecha" value="${ui.resFecha}" style="width:auto"></div>
      ${tabla(['Horario', 'Recurso', 'Cliente o grupo', 'Entrenador', 'Notas', 'Estado', ''], res.map((r) => `<tr><td>${esc(r.inicio)}–${esc(r.fin)}</td><td>${esc(nom('recursos', r.recursoId))}</td><td>${grupoDe(r) ? `<span class="chip info">Equipo o grupo</span> ${esc(grupoDe(r))}${r.contacto || r.telefono ? `<div class="muted small">${esc([r.contacto, r.telefono].filter(Boolean).join(' · '))}</div>` : ''}` : esc(nom('clientes', r.clienteId))}</td><td>${esc(nom('entrenadores', r.entrenadorId))}</td><td>${esc(r.notas || '')}</td><td>${r.estado === 'cancelada' ? chip('cancelada') : '<span class="chip ok">Confirmada</span>'}</td><td class="n">${r.estado === 'cancelada' ? '' : `<button class="mini danger" data-a="motivo" data-tipo="reserva" data-id="${r.id}">Cancelar</button>`}</td></tr>`), 'Sin reservaciones para ese día.')}</div>`;
  },

  reportes() {
    const d = ui.repDesde, h = ui.repHasta;
    const ing = R.ingresos(S.pagos, S.cargos, S.clientes, d, h);
    const porConcepto = {};
    S.pagos.filter((p) => !p.cancelado && p.fecha >= d && p.fecha <= h).forEach((p) => { const cg = by('cargos', p.cargoId) || {}, k = cg.conceptoId || (cg.pedidoId ? PED : ''); porConcepto[k] = (porConcepto[k] || 0) + p.monto; });
    const pat = {};
    S.cargos.filter((c) => c.fecha >= d && c.fecha <= h).forEach((c) => { const m = R.montoPatrocinado(c); if (m) pat[c.clienteId] = (pat[c.clienteId] || 0) + m; });
    const asis = {}; let nAsis = 0;
    S.asistencias.filter((a) => a.fecha >= d && a.fecha <= h).forEach((a) => { asis[a.areaId] = (asis[a.areaId] || 0) + 1; nAsis++; });
    const est = {}; S.membresias.forEach((m) => { const e = estadoM(m); est[e] = (est[e] || 0) + 1; });
    const conteo = (o, f) => Object.entries(o).sort((a, b) => b[1] - a[1]).map(([k, v]) => `<tr><td>${f(k)}</td><td class="n">${v}</td></tr>`);
    return cabeza('Reportes', `Del ${fecha(d)} al ${fecha(h)}`, `<input type="date" id="repDesde" data-ui="repDesde" value="${d}" style="width:auto"><input type="date" id="repHasta" data-ui="repHasta" value="${h}" style="width:auto">`)
      + `<div class="kpis"><div class="kpi"><span>Ingresos</span><b>${money(ing.total)}</b></div><div class="kpi"><span>Patrocinio otorgado</span><b>${money(Object.values(pat).reduce((s, v) => s + v, 0))}</b></div><div class="kpi"><span>Entradas</span><b>${nAsis}</b></div></div>
      <div class="cols">
        <div class="panel"><div class="head"><h3>Ingresos por área</h3><button class="mini" data-a="csvPagos">CSV de pagos</button></div>${barras(ing.porArea, areaNom)}</div>
        <div class="panel"><h3>Ingresos por tipo de cliente</h3>${barras(ing.porTipo, (k) => nom('tiposCliente', k, k))}</div>
        <div class="panel"><h3>Ingresos por concepto</h3>${barras(porConcepto, (k) => (k === PED ? 'Artículos de pedidos' : nom('conceptos', k, 'Sin concepto')))}</div>
        <div class="panel"><div class="head"><h3>Patrocinio por jugador</h3><button class="mini" data-a="csvPatrocinio">CSV</button></div><p class="muted small" style="margin:0">Diferencia entre el precio de público general y lo cobrado a clientes patrocinados.</p>${barras(pat, (k) => nom('clientes', k))}</div>
        <div class="panel"><div class="head"><h3>Entradas por área</h3><button class="mini" data-a="csvAsistencia">CSV</button></div>${tabla(['Área', '#Entradas'], conteo(asis, (k) => esc(nom('areas', k))), 'Sin entradas en el periodo.')}<p class="muted small" style="margin:0">La asistencia cubre los últimos 180 días con registro.</p></div>
        <div class="panel"><div class="head"><h3>Membresías por estado (hoy)</h3><button class="mini" data-a="csvMembresias">CSV</button></div>${tabla(['Estado', '#Cantidad'], conteo(est, chip), 'Sin membresías.')}</div>
      </div>`;
  },

  tallas() {
    const l = jugadoresTallas();
    const filas = l.map(({ c, eq }) => `<tr><td><a href="#clientes" data-a="verCliente" data-id="${c.id}">${esc(c.nombre)}</a></td><td>${esc(nom('equipos', eq))}</td>${PRENDAS.map(([k]) => `<td>${esc(tallasDe(c)[k]) || '<span class="chip warn">Pendiente</span>'}</td>`).join('')}<td>${esc(uniDe(c, eq).numero) || '—'}</td><td>${esc(uniDe(c, eq).leyenda) || '—'}</td><td class="n"><button class="mini" data-a="tallasForm" data-id="${c.id}" data-equipo="${esc(eq)}">Capturar</button></td></tr>`);
    const resumen = PRENDAS.map(([k, t]) => {
      const n = {}; l.forEach(({ c }) => { const v = tallasDe(c)[k]; if (v) n[v] = (n[v] || 0) + 1; });
      const falta = l.filter(({ c }) => !tallasDe(c)[k]).length;
      const fs = Object.keys(n).sort(ordenTalla).map((v) => `<tr><td>${esc(v)}</td><td class="n">${n[v]}</td></tr>`);
      if (falta) fs.push(`<tr><td><span class="chip warn">Pendiente</span></td><td class="n">${falta}</td></tr>`);
      return `<div class="panel"><h3>${t}</h3>${tabla(['Talla', '#Piezas'], fs, 'Sin jugadores.')}</div>`;
    }).join('');
    return cabeza('Tallas', 'Cachucha, jersey, pantalonera, número y leyenda del uniforme de los jugadores de equipo o patrocinados', `<button data-a="csvTallas">CSV</button>`)
      + `<div class="row"><select id="t-equipo" data-ui="tEquipo" class="grow" aria-label="Equipo"><option value="">Todos los equipos</option>${opts('equipos', ui.tEquipo)}</select>
        <select id="t-pend" data-ui="tPend" class="grow" aria-label="Mostrar"><option value="">Todos los jugadores</option><option value="1"${ui.tPend ? ' selected' : ''}>Solo con tallas pendientes</option></select></div>
      <div class="panel"><h3>Uniformes (${l.length})</h3><p class="muted small" style="margin:0">Un jugador aparece una vez por cada equipo en el que está: las tallas son del jugador; el número y la leyenda, de cada equipo.</p>${tabla(['Jugador', 'Equipo', ...PRENDAS.map((p) => p[1]), 'Número', 'Leyenda', ''], filas, 'No hay jugadores que mostrar. Asigna uno o más equipos al cliente en su expediente para que aparezca aquí.')}</div>
      <h2 style="margin:0">Resumen para pedido</h2><div class="cols">${resumen}</div>`;
  },

  pedidos() {
    const p = ui.pedidoId && by('pedidos', ui.pedidoId);
    if (p) return vistaPedido(p);
    const lista = [...S.pedidos].sort((a, b) => (a.fecha !== b.fecha ? (a.fecha < b.fecha ? 1 : -1) : (a.creado || '') < (b.creado || '') ? 1 : -1));
    return cabeza('Pedidos', 'Pedidos especiales de artículos para venta en el gimnasio: sudaderas, chamarras, cachuchas, jerseys…', `<button class="pri" data-a="pedidoForm">Nuevo pedido</button>`)
      + `<div class="panel">${tabla(['Pedido', 'Fecha', 'Proveedor', 'Entrega estimada', '#Piezas', '#Importe', 'Estado'], lista.map((x) => `<tr class="click" data-a="verPedido" data-id="${x.id}"><td>${esc(x.nombre)}</td><td>${fecha(x.fecha)}</td><td>${esc(x.proveedor || '—')}</td><td>${fecha(x.entrega)}</td><td class="n">${piezasDe(x)}</td><td class="n">${money(importeDe(x))}</td><td>${chip(x.estado)}</td></tr>`), 'Aún no hay pedidos. Usa “Nuevo pedido”.')}</div>`;
  },

  catalogos() {
    const tabs = [...Object.entries(CAT).map(([k, c]) => [k, c.titulo]), ['precios', 'Listas de precios'], ['config', 'Configuración']];
    let cuerpo;
    if (ui.cat === 'precios') cuerpo = vistaPrecios();
    else if (ui.cat === 'config') cuerpo = `<form class="panel" data-form="config"><h3>Configuración</h3><div class="form"><label class="f">Días de aviso antes del vencimiento<input type="number" name="diasAviso" id="cfg-aviso" min="1" max="60" value="${diasAviso()}" required></label><div style="align-self:end"><button class="pri">Guardar</button></div></div></form>`;
    else {
      const def = CAT[ui.cat];
      const filas = [...S[ui.cat]].sort((a, b) => String(a.nombre).localeCompare(b.nombre, 'es')).map((x) => `<tr>${def.campos.map((f) => `<td>${celda(f, x[f.k])}</td>`).join('')}<td>${x.activo === false ? chip('cancelada').replace('Cancelada', 'Inactivo') : '<span class="chip ok">Activo</span>'}</td><td class="n"><button class="mini" data-a="catForm" data-id="${x.id}">Editar</button> ${ui.cat === 'tiposCliente' && x.id === R.GENERAL ? '' : `<button class="mini" data-a="catActivo" data-id="${x.id}">${x.activo === false ? 'Activar' : 'Desactivar'}</button>`}</td></tr>`);
      cuerpo = `<div class="panel"><div class="head"><h3>${def.titulo}</h3><button class="pri" data-a="catForm">Agregar</button></div>${def.nota ? `<p class="muted small" style="margin:0">${def.nota}</p>` : ''}${tabla([...def.campos.map((f) => f.l), 'Estado', ''], filas, 'Este catálogo está vacío. Usa “Agregar”.')}</div>`;
    }
    return cabeza('Catálogos', 'Lo que se desactiva deja de ofrecerse, pero conserva su historial')
      + `<div class="tabs" role="tablist">${tabs.map(([k, t]) => `<button role="tab" aria-selected="${ui.cat === k}" data-a="set" data-k="cat" data-v="${k}">${t}</button>`).join('')}</div>${cuerpo}`;
  },
};

// ---------- Fragmentos ----------
function filaMembresia(m, e, conCliente) {
  const ses = m.sesionesTotales ? `${m.sesionesTotales - (m.sesionesUsadas || 0)} de ${m.sesionesTotales}` : '—';
  const acc = [];
  if (e !== 'cancelada') acc.push(`<button class="mini" data-a="vender" data-cliente="${m.clienteId}" data-concepto="${m.conceptoId}">Renovar</button>`);
  if (e === 'suspendida') acc.push(`<button class="mini" data-a="reactivar" data-id="${m.id}">Reactivar</button>`);
  else if (e !== 'cancelada' && e !== 'vencida') acc.push(`<button class="mini" data-a="motivo" data-tipo="suspender" data-id="${m.id}">Suspender</button>`);
  if (e !== 'cancelada') acc.push(`<button class="mini danger" data-a="motivo" data-tipo="membresia" data-id="${m.id}">Cancelar</button>`);
  return `<tr>${conCliente ? `<td>${esc(nom('clientes', m.clienteId))}</td>` : ''}<td>${esc(nom('conceptos', m.conceptoId))}</td><td>${fecha(m.inicio)}</td><td>${fecha(m.fin)}</td><td>${ses}</td><td>${chip(e)}${m.motivo ? ` <span class="muted small">${esc(m.motivo)}</span>` : ''}</td><td class="n">${acc.join(' ')}</td></tr>`;
}
function filaCargo(c, conCliente) {
  const e = R.estadoCargo(c, S.pagos), s = R.saldoCargo(c, S.pagos);
  return `<tr><td>C-${c.folio}</td><td>${fecha(c.fecha)}</td>${conCliente ? `<td>${esc(nom('clientes', c.clienteId))}</td>` : ''}<td>${esc(conceptoDe(c))}${c.descuento ? ` <span class="muted small">desc. ${money(c.descuento)}</span>` : ''}</td><td class="n">${money(c.total)}</td><td class="n">${s ? money(s) : '—'}</td><td>${chip(e)}</td><td class="n">${s > 0 ? `<button class="mini pri" data-a="pagoForm" data-id="${c.id}">Cobrar</button> ` : ''}${c.cancelado ? '' : `<button class="mini danger" data-a="motivo" data-tipo="cargo" data-id="${c.id}">Cancelar</button>`}</td></tr>`;
}
function expediente(c) {
  const h = hoy(), ed = R.edad(c.nacimiento, h);
  const ms = S.membresias.filter((m) => m.clienteId === c.id).sort((a, b) => (a.fin < b.fin ? 1 : -1));
  const cs = S.cargos.filter((x) => x.clienteId === c.id).sort((a, b) => (b.folio || 0) - (a.folio || 0));
  const ps = S.pagos.filter((x) => x.clienteId === c.id).sort((a, b) => (b.folio || 0) - (a.folio || 0));
  const as = S.asistencias.filter((a) => a.clienteId === c.id).sort((a, b) => (a.fecha + a.hora < b.fecha + b.hora ? 1 : -1)).slice(0, 20);
  const saldo = saldoCliente(c.id);
  const d = (l, v) => `<div><span>${l}</span>${esc(v || '—')}</div>`;
  return `<div><button class="mini" data-a="verCliente" data-id="">← Clientes</button></div>`
    + cabeza(esc(c.nombre), `${esc(nom('tiposCliente', c.tipoClienteId))}${equiposDe(c).length ? ' · ' + esc(equiposTxt(c)) : ''}${c.activo === false ? ' · Inactivo' : ''}`,
      `<button data-a="clienteForm" data-id="${c.id}">Editar</button><button class="pri" data-a="vender" data-cliente="${c.id}">Vender</button>`)
    + (saldo ? `<div class="note bad">Saldo pendiente: <b>${money(saldo)}</b></div>` : '')
    + `<div class="panel"><div class="dl">${d('Teléfono', c.telefono)}${d('Correo', c.correo)}${d('Nacimiento', c.nacimiento ? `${fecha(c.nacimiento)} (${ed} años)` : '')}${d('Tutor', c.tutor)}${d('Contacto de emergencia', [c.emergenciaNombre, c.emergenciaTel].filter(Boolean).join(' · '))}${d('Notas médicas', c.notasMedicas)}${d('Tallas', PRENDAS.filter(([k]) => tallasDe(c)[k]).map(([k, l]) => `${l} ${tallasDe(c)[k]}`).join(' · '))}${d('Uniforme', (equiposDe(c).length ? equiposDe(c) : ['']).map((eq) => { const u = uniDe(c, eq), t = [u.numero && `#${u.numero}`, u.leyenda && `“${u.leyenda}”`].filter(Boolean).join(' '); return t && (eq ? `${nom('equipos', eq)}: ${t}` : t); }).filter(Boolean).join(' · '))}</div></div>
    <div class="panel"><h3>Membresías y paquetes</h3>${tabla(['Concepto', 'Inicio', 'Fin', 'Sesiones', 'Estado', ''], ms.map((m) => filaMembresia(m, estadoM(m), false)), 'Sin membresías. Usa “Vender”.')}</div>
    <div class="panel"><h3>Cargos</h3>${tabla(['Folio', 'Fecha', 'Concepto', '#Total', '#Saldo', 'Estado', ''], cs.map((x) => filaCargo(x, false)), 'Sin cargos.')}</div>
    <div class="panel"><h3>Pagos</h3>${tabla(['Folio', 'Fecha', 'Forma', '#Monto', 'Estado', ''], ps.map((p) => `<tr><td>P-${p.folio}</td><td>${fecha(p.fecha)}</td><td>${esc(nom('formasPago', p.formaPagoId))}</td><td class="n">${money(p.monto)}</td><td>${p.cancelado ? chip('cancelado') : '<span class="chip ok">Vigente</span>'}</td><td class="n"><button class="mini" data-a="recibo" data-id="${p.id}">Recibo</button></td></tr>`), 'Sin pagos.')}</div>
    <div class="panel"><h3>Últimas entradas</h3>${tabla(['Fecha', 'Hora', 'Área'], as.map((a) => `<tr><td>${fecha(a.fecha)}</td><td>${esc(a.hora)}</td><td>${esc(nom('areas', a.areaId))}${a.excepcion ? ' <span class="chip warn">Excepción</span>' : ''}</td></tr>`), 'Sin entradas registradas.')}</div>`;
}

function vistaPedido(p) {
  const ls = lineasDe(p).sort((a, b) => String(a.articulo).localeCompare(b.articulo, 'es') || ordenTalla(a.talla || '', b.talla || '') || paraQuien(a).localeCompare(paraQuien(b), 'es'));
  const fijo = pedidoFijo(p), res = {};
  ls.forEach((l) => { const k = `${l.articulo}\u0001${l.talla || ''}`; res[k] = (res[k] || 0) + l.cantidad; });
  const entregadas = ls.filter((l) => l.entregado).reduce((t, l) => t + l.cantidad, 0);
  const filas = ls.map((l) => {
    const acc = fijo ? [] : [`<button class="mini" data-a="lineaEntregada" data-id="${l.id}">${l.entregado ? 'Deshacer entrega' : 'Entregar'}</button>`, `<button class="mini" data-a="lineaForm" data-id="${l.id}">Editar</button>`, `<button class="mini danger" data-a="lineaQuitar" data-id="${l.id}">Quitar</button>`];
    const cg = cargoDeLinea(l), saldo = cg ? R.saldoCargo(cg, S.pagos) : 0;
    if (l.clienteId && p.estado !== 'cancelado' && (!cg || saldo > 0)) acc.unshift(`<button class="mini pri" data-a="lineaCobrar" data-id="${l.id}">${cg ? 'Cobrar saldo' : 'Cobrar'}</button>`);
    return `<tr><td>${esc(l.articulo)}</td><td>${esc(l.talla || '—')}</td><td class="n">${l.cantidad}</td><td>${esc(paraQuien(l))}</td><td>${esc(l.notas || '')}</td><td class="n">${l.precio ? money(l.precio) : '—'}</td><td class="n">${l.precio ? money(l.cantidad * l.precio) : '—'}</td><td>${cg ? `${chip(R.estadoCargo(cg, S.pagos))} <span class="muted small">C-${cg.folio}</span>` : '—'}</td><td>${l.entregado ? '<span class="chip ok">Entregado</span>' : '<span class="chip warn">Por entregar</span>'}</td><td class="n">${acc.join(' ')}</td></tr>`;
  });
  const d = (l, v) => `<div><span>${l}</span>${esc(v || '—')}</div>`;
  return `<div><button class="mini" data-a="verPedido" data-id="">← Pedidos</button></div>`
    + cabeza(esc(p.nombre), chip(p.estado), `<button data-a="csvPedido">CSV</button><button data-a="pedidoForm" data-id="${p.id}">Editar pedido</button>${fijo ? '' : '<button class="pri" data-a="lineaForm">Agregar artículo</button>'}`)
    + `<div class="panel"><div class="dl">${d('Fecha del pedido', fecha(p.fecha))}${d('Proveedor', p.proveedor)}${d('Entrega estimada', p.entrega ? fecha(p.entrega) : '')}${d('Piezas', `${piezasDe(p)} (${entregadas} entregadas)`)}${d('Importe', money(importeDe(p)))}${d('Notas', p.notas)}</div></div>
    <div class="panel"><h3>Artículos</h3><p class="muted small" style="margin:0">“Cobrar” registra el cargo de ese artículo a nombre del cliente y el pago que recibas; después aparece en Cobros y en el corte. Se cobran aquí los artículos pedidos por un cliente y con precio.</p>${tabla(['Artículo', 'Talla', '#Cant.', 'Para', 'Detalle', '#P. unitario', '#Importe', 'Cobro', 'Entrega', ''], filas, fijo ? 'Este pedido no tiene artículos.' : 'Sin artículos todavía. Usa “Agregar artículo”.')}</div>
    <div class="panel"><h3>Resumen para el proveedor</h3>${tabla(['Artículo', 'Talla', '#Piezas'], Object.keys(res).map((k) => { const [a, t] = k.split('\u0001'); return `<tr><td>${esc(a)}</td><td>${esc(t || '—')}</td><td class="n">${res[k]}</td></tr>`; }), 'Sin artículos.')}</div>`;
}

